def card(slug,name,ic,c1,c2,badge='',stake='10 credits',playable=True,R=''):
    href=f'{R}spel/{slug}.html' if playable else f'{R}spellen.html'
    return f'''<div class="card" data-name="{name}"><div class="art" style="background:radial-gradient(circle at 50% 35%,{c1},{c2})"><i>{ic}</i><b>{name}</b></div>
{f'<span class="badge">{badge}</span>' if badge else ''}<span class="stake">{stake}</span>
<div class="ov"><button class="fav" aria-label="Favoriet">♡</button><a class="btn" data-play href="{href}">Spelen</a><a class="btn g" href="{href}">Proberen</a></div></div>'''
def gcards(R,filt=None):
    return ''.join(card(s,n,i,a,b,bd,R=R) for s,n,i,a,b,cat,bd in GAMES if not filt or cat in filt)
def ecards(R,k=8):return ''.join(card('x',n,i,a,b,'',playable=False,R=R) for n,i,a,b in EXTRA[:k])
