BET='<div class="ctl"><span>Saldo: <b data-cred></b> credits</span><label>Inzet <select id="bet"><option>10</option><option>20</option><option>50</option><option>100</option></select></label>{b}</div><p class="msg" id="msg" aria-live="polite"></p>'
def gpage(slug,name,rules,inner,js):
    page(f'spel/{slug}.html',name,f'<main class="game"><a href="../spellen.html">← Terug naar de lobby</a><h1>{name}</h1><div class="gbox">{inner}</div><div class="rules"><h3>Spelregels</h3>{rules}<p><b>Alleen virtuele credits – geen echt geld, geen prijzen.</b></p></div></main><script>const bet=()=>+document.getElementById("bet").value,say=t=>document.getElementById("msg").textContent=t;function pay(b){{if(Q.credits()<b){{say("Onvoldoende credits. Reset je saldo via Account.");return false}}Q.setCredits(Q.credits()-b);return true}}{js}</script>')
SLOT='''const S=SYM,R=document.getElementById('reels');let cells=[];for(let i=0;i<15;i++){const d=document.createElement('div');d.textContent=S[i%S.length];R.appendChild(d);cells.push(d)}
document.getElementById('go').onclick=()=>{const b=bet();if(!pay(b))return;let t=0;const iv=setInterval(()=>{cells.forEach(c=>{c.classList.remove('win');c.textContent=S[Math.random()*S.length|0]});if(++t>12){clearInterval(iv);done(b)}},70)};
function done(b){let win=0;for(let r=0;r<3;r++){const row=cells.slice(r*5,r*5+5).map(c=>c.textContent);let f=row[0]==S[5]?row.find(x=>x!=S[5])||S[5]:row[0],n=0;for(const x of row){if(x==f||x==S[5])n++;else break}
if(n>=3){win+=b*({3:1,4:4,5:15}[n])*(S.indexOf(f)>=3?2:1)/3;for(let k=0;k<n;k++)cells[r*5+k].classList.add('win')}}win=Math.round(win);Q.setCredits(Q.credits()+win);say(win?`Gewonnen: ${win} credits!`:'Helaas, geen winst. Probeer opnieuw.')}'''
gpage('amberwoud','Amberwoud','<p>5 rollen, 3 rijen. Drie of meer gelijke symbolen vanaf links op een rij leveren winst op. De ✨ (wild) vervangt elk symbool. 🦌 en 🌰 betalen dubbel.</p>','<div class="reels" id="reels"></div>'+BET.format(b='<button class="btn" id="go">Draaien</button>'),"const SYM=['🍂','☀️','🟠','🦌','🌰','✨'];"+SLOT)
gpage('noorderlicht','Noorderlicht','<p>5 rollen, 3 rijen onder het poollicht. Drie of meer gelijke symbolen vanaf links op een rij winnen. 🌠 is wild; 🐻‍❄️ en 🦉 betalen dubbel.</p>','<div class="reels" id="reels" style="background:linear-gradient(#123a4a,#2a1458);padding:8px;border-radius:8px"></div>'+BET.format(b='<button class="btn" id="go">Draaien</button>'),"const SYM=['❄️','⭐','🌙','🐻‍❄️','🦉','🌠'];"+SLOT)
gpage('wiel','Quinara Wiel','<p>Kies je inzet en draai het wiel. De vermenigvuldiger waar de wijzer op stopt bepaalt je winst (0× betekent verlies).</p>','<canvas id="c" width="360" height="360"></canvas>'+BET.format(b='<button class="btn" id="go">Draai</button>'),'''
const M=[0,1.5,0,2,0.5,0,3,0,1.2,5,0,1.5],C=document.getElementById('c').getContext('2d');let ang=0,spin=false;
function draw(){C.clearRect(0,0,360,360);const n=M.length;for(let i=0;i<n;i++){C.beginPath();C.moveTo(180,180);C.arc(180,180,170,ang+i*2*Math.PI/n,ang+(i+1)*2*Math.PI/n);C.fillStyle=i%2?'#00813D':'#FF5900';C.fill();C.save();C.translate(180,180);C.rotate(ang+(i+.5)*2*Math.PI/n);C.fillStyle='#fff';C.font='bold 20px sans-serif';C.fillText(M[i]+'×',110,7);C.restore()}
C.fillStyle='#fff';C.beginPath();C.moveTo(180,2);C.lineTo(168,28);C.lineTo(192,28);C.fill()}draw();
document.getElementById('go').onclick=()=>{if(spin)return;const b=bet();if(!pay(b))return;spin=true;let v=.4+Math.random()*.3;const t=setInterval(()=>{ang+=v;v*=.985;draw();if(v<.002){clearInterval(t);spin=false;const n=M.length;let a=((-Math.PI/2-ang)%(2*Math.PI)+4*Math.PI)%(2*Math.PI);const m=M[Math.floor(a/(2*Math.PI/n))];const w=Math.round(b*m);Q.setCredits(Q.credits()+w);say(w?`${m}× – je wint ${w} credits!`:'0× – helaas!')}},16)}''')
gpage('dauwdrop','Dauwdrop','<p>Laat een dauwdruppel vallen. Hij stuitert langs de pinnen en landt in een vakje met een vermenigvuldiger.</p>','<canvas id="c" width="420" height="420"></canvas>'+BET.format(b='<button class="btn" id="go">Laat vallen</button>'),'''
const M=[5,2,1.2,.5,.3,.5,1.2,2,5],X=document.getElementById('c').getContext('2d'),W=420,rows=8;
function board(){X.clearRect(0,0,W,W);X.fillStyle='#cfe';for(let r=0;r<rows;r++)for(let i=0;i<=r+1;i++){X.beginPath();X.arc(W/2+(i-(r+1)/2)*42,50+r*40,4,0,7);X.fill()}
M.forEach((m,i)=>{X.fillStyle=m>=2?'#FF5900':m>=1?'#079447':'#444';X.fillRect(16+i*44,380,40,30);X.fillStyle='#fff';X.font='bold 13px sans-serif';X.fillText(m+'×',22+i*44,400)})}board();
document.getElementById('go').onclick=()=>{const b=bet();if(!pay(b))return;let pos=0,r=0,x=W/2,y=20;const path=[];for(let i=0;i<rows;i++){pos+=Math.random()<.5?0:1;path.push(pos)}
const t=setInterval(()=>{board();if(r<rows){x=W/2+(path[r]-(r+1)/2+.5)*42-21;y=50+r*40+15;r++}else{clearInterval(t);const m=M[path[rows-1]];const w=Math.round(b*m);Q.setCredits(Q.credits()+w);say(`${m}× – ${w} credits terug`);y=370}
X.fillStyle='#7fd8ff';X.beginPath();X.arc(x+21,y,8,0,7);X.fill()},180)}''')
gpage('hoger-lager','Hoger of Lager','<p>Raad of de volgende kaart hoger of lager is dan de huidige. Goed geraden: 1,9× je inzet. Gelijk: inzet terug.</p>','<div id="card" style="font-size:72px;background:#fff;color:#222;width:120px;margin:auto;border-radius:10px;padding:20px 0">7♠</div>'+BET.format(b='<button class="btn" id="hi">Hoger</button><button class="btn g" id="lo">Lager</button>'),'''
const V=['2','3','4','5','6','7','8','9','10','B','V','H','A'],SU=['♠','♥','♦','♣'];let cur=5;const show=(v,s)=>{const c=document.getElementById('card');c.textContent=V[v]+s;c.style.color=(s=='♥'||s=='♦')?'#c00':'#222'};
function g(up){const b=bet();if(!pay(b))return;const n=Math.random()*13|0,s=SU[Math.random()*4|0];show(n,s);if(n==cur){Q.setCredits(Q.credits()+b);say('Gelijk – inzet terug.')}else if((n>cur)==up){const w=Math.round(b*1.9);Q.setCredits(Q.credits()+w);say(`Goed! +${w} credits`)}else say('Mis! Probeer opnieuw.');cur=n}
document.getElementById('hi').onclick=()=>g(true);document.getElementById('lo').onclick=()=>g(false);''')
gpage('reactie','Reactie','<p>Start de ronde: de vermenigvuldiger stijgt. Klik op <b>Uitbetalen</b> voordat de raket ontploft. Te laat? Dan verlies je je inzet.</p>','<div id="mul" style="font-size:72px;font-family:Barlow Condensed;font-weight:800">1.00×</div><div style="font-size:50px" id="rk">🚀</div>'+BET.format(b='<button class="btn" id="go">Start</button><button class="btn g" id="co" disabled>Uitbetalen</button>'),'''
let m=1,run=false,b=0,crash,t;const go=document.getElementById('go'),co=document.getElementById('co'),mu=document.getElementById('mul');
go.onclick=()=>{if(run)return;b=bet();if(!pay(b))return;run=true;m=1;crash=Math.max(1,0.97/(1-Math.random()));document.getElementById('rk').textContent='🚀';co.disabled=false;go.disabled=true;say('');
t=setInterval(()=>{m*=1.012;mu.textContent=m.toFixed(2)+'×';if(m>=crash){clearInterval(t);run=false;co.disabled=true;go.disabled=false;document.getElementById('rk').textContent='💥';say('Ontploft bij '+crash.toFixed(2)+'× – inzet kwijt.')}},60)};
co.onclick=()=>{if(!run)return;clearInterval(t);run=false;co.disabled=true;go.disabled=false;const w=Math.round(b*m);Q.setCredits(Q.credits()+w);say(`Uitbetaald bij ${m.toFixed(2)}×: +${w} credits`)}''')
